    const min = n > 4 && !r.tryNil() ? r.float() : undefined;
    const max = n > 5 && !r.tryNil() ? r.float() : undefined;
    const choices = n > 6 && !r.tryNil() ? readList(r, () => r.str()) : undefined;
    const description = n > 7 && !r.tryNil() ? r.str() : undefined;
    const completion = n > 8 && !r.tryNil() ? CompletionSpecCodec.read(r) : undefined;
    for (let i = 9; i < n; i++) r.skip();
