    if (v.description === undefined || v.description === null) w.nil(); else w.str(v.description);
    writeList(w, v.args, (x) => CommandArgCodec.write(w, x));
    if (v.children === undefined || v.children === null) w.nil(); else writeList(w, v.children, (x) => CommandNodeCodec.write(w, x));
