    const args = readList(r, () => CommandArgCodec.read(r));
    const children = n > 4 && !r.tryNil() ? readList(r, () => CommandNodeCodec.read(r)) : undefined;
    const runnable = n > 5 && !r.tryNil() ? r.bool() : true;
