    if (v.barColor === undefined || v.barColor === null) w.nil(); else w.uint(v.barColor);
    if (v.head === undefined || v.head === null) w.nil(); else w.str(v.head);
    if (v.color === undefined || v.color === null) w.nil(); else w.uint(v.color);
    if (v.frames === undefined || v.frames === null) w.nil(); else writeList(w, v.frames, (x) => SlotItemCodec.write(w, x));
    w.uint(v.frameMs ?? 500);
    w.bool(v.hideTooltip ?? false);
