    const attached = r.bool();
    const name = n > 3 && !r.tryNil() ? r.str() : undefined;
    const uuid = n > 4 && !r.tryNil() ? r.str() : undefined;
    const alive = n > 5 && !r.tryNil() ? r.bool() : true;
