/** Payload of message `query.entities` (id 0x89), sent by node with reliable delivery. Answered by `query.entities.result`; default timeout 10000 ms. */
export interface QueryEntities {
  /** The player's position when absent. */
  center?: Vec3d | undefined;
  /** Blocks, at most 128. Default `32`. */
  radius?: number | undefined;
  /** Entity type ids; every type when absent. */
  types?: string[] | undefined;
  /** At most 1024, nearest first. Default `256`. */
  limit?: number | undefined;
}
/** Wire codec for {@link QueryEntities}. */
export const QueryEntitiesCodec: Codec<QueryEntities> = {
  write(w, v) {
    w.arrayHeader(4);
    if (v.center === undefined || v.center === null) w.nil(); else Vec3dCodec.write(w, v.center);
    w.f32(v.radius ?? 32);
    if (v.types === undefined || v.types === null) w.nil(); else writeList(w, v.types, (x) => w.str(x));
    w.uint(v.limit ?? 256);
  },
  read(r) {
    const n = r.arrayHeader();
    const center = n > 0 && !r.tryNil() ? Vec3dCodec.read(r) : undefined;
    const radius = n > 1 && !r.tryNil() ? r.float() : 32;
    const types = n > 2 && !r.tryNil() ? readList(r, () => r.str()) : undefined;
    const limit = n > 3 && !r.tryNil() ? r.uint() : 256;
    for (let i = 4; i < n; i++) r.skip();
    return { center, radius, types, limit };
  },
};

/** Payload of message `query.entities.result` (id 0x8a), sent by mod with reliable delivery. */
export interface QueryEntitiesResult {
  entities: QueriedEntity[];
}
/** Wire codec for {@link QueryEntitiesResult}. */
export const QueryEntitiesResultCodec: Codec<QueryEntitiesResult> = {
  write(w, v) {
    w.arrayHeader(1);
    writeList(w, v.entities, (x) => QueriedEntityCodec.write(w, x));
  },
  read(r) {
    const n = r.arrayHeader();
    if (n < 1) throw new WireError('invalid_message', 'query.entities.result: expected at least 1 fields, got ' + n);
    const entities = readList(r, () => QueriedEntityCodec.read(r));
    for (let i = 1; i < n; i++) r.skip();
    return { entities };
  },
};

/** Payload of message `query.blocks` (id 0x8b), sent by node with reliable delivery. Answered by `query.blocks.result`; default timeout 10000 ms. */
export interface QueryBlocks {
  min: Vec3i;
  /** inclusive; at most 65536 blocks. */
  max: Vec3i;
  /** Block ids to report; every non-air block when absent. */
  blocks?: string[] | undefined;
  /** At most 65536. Default `4096`. */
  limit?: number | undefined;
}
/** Wire codec for {@link QueryBlocks}. */
export const QueryBlocksCodec: Codec<QueryBlocks> = {
  write(w, v) {
    w.arrayHeader(4);
    Vec3iCodec.write(w, v.min);
    Vec3iCodec.write(w, v.max);
    if (v.blocks === undefined || v.blocks === null) w.nil(); else writeList(w, v.blocks, (x) => w.str(x));
    w.uint(v.limit ?? 4096);
  },
  read(r) {
    const n = r.arrayHeader();
    if (n < 2) throw new WireError('invalid_message', 'query.blocks: expected at least 2 fields, got ' + n);
    const min = Vec3iCodec.read(r);
    const max = Vec3iCodec.read(r);
    const blocks = n > 2 && !r.tryNil() ? readList(r, () => r.str()) : undefined;
    const limit = n > 3 && !r.tryNil() ? r.uint() : 4096;
    for (let i = 4; i < n; i++) r.skip();
    return { min, max, blocks, limit };
  },
};

/** Payload of message `query.blocks.result` (id 0x8c), sent by mod with reliable delivery. */
export interface QueryBlocksResult {
  /** x, y, z triples. */
  positions: Int32Array;
  /** Block ids. */
  palette: string[];
  /** One palette index per position. */
  ids: Uint16Array;
  /** False when part of the box is not loaded or the limit cut it. */
  complete: boolean;
}
/** Wire codec for {@link QueryBlocksResult}. */
export const QueryBlocksResultCodec: Codec<QueryBlocksResult> = {
  write(w, v) {
    w.arrayHeader(4);
    w.typedArray(v.positions);
    writeList(w, v.palette, (x) => w.str(x));
    w.typedArray(v.ids);
    w.bool(v.complete);
  },
  read(r) {
    const n = r.arrayHeader();
    if (n < 4) throw new WireError('invalid_message', 'query.blocks.result: expected at least 4 fields, got ' + n);
    const positions = r.i32Array();
    const palette = readList(r, () => r.str());
    const ids = r.u16Array();
    const complete = r.bool();
    for (let i = 4; i < n; i++) r.skip();
    return { positions, palette, ids, complete };
  },
};

